<article <?php post_class( 'featured-post' ); ?>><a class="featured-post-image" href="<?php the_permalink(); ?>" aria-hidden="true" tabindex="-1"><?php if ( has_post_thumbnail() ) { the_post_thumbnail( 'large' ); } else { ?><span class="post-thumb placeholder"></span><?php } ?></a><div class="featured-post-content"><p class="eyebrow"><?php esc_html_e( 'Featured article', 'kimpu-multipurpose' ); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php get_template_part( 'template-parts/blog/post-meta' ); ?><?php if ( kimpu_blog_show( 'excerpt' ) ) : ?><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 36 ) ); ?></p><?php endif; ?><a class="button" href="<?php the_permalink(); ?>"><?php esc_html_e( 'Read article', 'kimpu-multipurpose' ); ?></a></div></article>
